// Offline support. Network-first so a deployed update shows up on the next load; the cache
// is only a fallback for when there's no connection (e.g. printing in the garage).
// The file list and cache name live in precache.js, generated by tools/make-precache.mjs.
// Browsers check imported scripts for changes too, so a new list installs a new worker.
importScripts("precache.js");
const CACHE = self.CACHE_NAME;

self.addEventListener("install", (event) => {
	event.waitUntil(
		(async () => {
			const cache = await caches.open(CACHE);
			// One missing file shouldn't stop the rest from being cached.
			await Promise.allSettled(self.PRECACHE.map((u) => cache.add(u)));
			await self.skipWaiting();
		})(),
	);
});

self.addEventListener("activate", (event) => {
	event.waitUntil(
		(async () => {
			for (const key of await caches.keys()) if (key !== CACHE) await caches.delete(key);
			await self.clients.claim();
		})(),
	);
});

self.addEventListener("fetch", (event) => {
	const req = event.request;
	if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
	event.respondWith(
		(async () => {
			const cache = await caches.open(CACHE);
			try {
				const res = await fetch(req);
				if (res.ok) cache.put(req, res.clone());
				return res;
			} catch {
				const hit = await cache.match(req, { ignoreSearch: true });
				if (hit) return hit;
				throw new Error(`offline and not cached: ${req.url}`);
			}
		})(),
	);
});
